                if len(files) > 1:
                    prefix += fname + ":"
                if "-n" in flags:
                    prefix += str(lineno) + ":"
                results.append(prefix + line + "\n")
            if "-l" in flags and file_matched:
                results.append(fname + "\n")
    return "".join(results)
```

